insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000300061', '40000000-0000-4000-8000-000000030006', 'O argumento de um logaritmo real deve ser estritamente positivo.', 1), ('60000000-0000-4000-8000-000000300062', '40000000-0000-4000-8000-000000030006', 'Imponha que x menos a seja maior do que zero.', 2)
