insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030011', '$f^{\prime}(x)=\frac{2}{(x+3)^2}.$', 'A regra do quociente exige atenção à ordem da subtração. Neste caso, as derivadas das duas expressões lineares são iguais a 1, então os termos com x se cancelam e resta apenas a diferença entre as constantes.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000300111', '40000000-0000-4000-8000-000000030011', 'Nomeie as partes', '$u=x+1, v=x+3 e u^{\prime}=v^{\prime}=1.$', 1), ('70000000-0000-4000-8000-000000300112', '40000000-0000-4000-8000-000000030011', 'Aplique a regra', '$f^{\prime}(x)=\frac{(x+3)-(x+1)}{(x+3)^2}.$', 2), ('70000000-0000-4000-8000-000000300113', '40000000-0000-4000-8000-000000030011', 'Simplifique', '$f^{\prime}(x)=\frac{2}{(x+3)^2}.$', 3)
