insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000030015', '50000000-0000-4000-8000-000000300151') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000030015', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000300151', '40000000-0000-4000-8000-000000030015', 'Use a regra do quociente: derivada do numerador vezes denominador, menos numerador vezes derivada do denominador.', 1), ('60000000-0000-4000-8000-000000300152', '40000000-0000-4000-8000-000000030015', 'As duas expressões lineares têm derivada igual a 1.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030015', '$f^{\prime}(x)=\frac{-3}{(x+2)^2}.$', 'A regra do quociente exige atenção à ordem da subtração. Neste caso, as derivadas das duas expressões lineares são iguais a 1, então os termos com x se cancelam e resta apenas a diferença entre as constantes.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000300151', '40000000-0000-4000-8000-000000030015', 'Nomeie as partes', '$u=x+5, v=x+2 e u^{\prime}=v^{\prime}=1.$', 1), ('70000000-0000-4000-8000-000000300152', '40000000-0000-4000-8000-000000030015', 'Aplique a regra', '$f^{\prime}(x)=\frac{(x+2)-(x+5)}{(x+2)^2}.$', 2), ('70000000-0000-4000-8000-000000300153', '40000000-0000-4000-8000-000000030015', 'Simplifique', '$f^{\prime}(x)=\frac{-3}{(x+2)^2}.$', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000030016', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000006', 'multiple_choice', 'medium', 'published', 'A área de um quadrado é $A=s^2$. Quando $s=2$ cm e o lado cresce a 3 cm/s, qual é $dA/dt$?')
