insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030021', '$x=-1$.', 'Os pontos críticos localizam candidatos a extremos, mas ainda precisam ser classificados. A segunda derivada informa a concavidade: negativa significa que o gráfico se curva para baixo, que é a característica de um máximo local.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000300211', '40000000-0000-4000-8000-000000030021', 'Derive', '$f^{\prime}(x)=3(x-1)(x+1).$', 1), ('70000000-0000-4000-8000-000000300212', '40000000-0000-4000-8000-000000030021', 'Encontre candidatos', '$f^{\prime}(x)=0\Rightarrow x=-1 ou x=1.$', 2), ('70000000-0000-4000-8000-000000300213', '40000000-0000-4000-8000-000000030021', 'Classifique', '$f^{\prime\prime}(x)=6x<0$ em $x=-1.$', 3)
