insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000300311', '40000000-0000-4000-8000-000000030031', 'A', '$0.5x^4+C$', 1), ('50000000-0000-4000-8000-000000300312', '40000000-0000-4000-8000-000000030031', 'B', '$6x^2+C$', 2), ('50000000-0000-4000-8000-000000300313', '40000000-0000-4000-8000-000000030031', 'C', '$2x^4+C$', 3), ('50000000-0000-4000-8000-000000300314', '40000000-0000-4000-8000-000000030031', 'D', '$0.5x^3+C$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000030031', '50000000-0000-4000-8000-000000300311') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000030031', '30000000-0000-4000-8000-000000000034', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000300311', '40000000-0000-4000-8000-000000030031', 'Na integração da potência, aumente o expoente em uma unidade.', 1), ('60000000-0000-4000-8000-000000300312', '40000000-0000-4000-8000-000000030031', 'Divida o coeficiente pelo novo expoente e acrescente a constante C.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000030031', '$0.5x^4+C$.', 'A regra da potência para primitivas desfaz a derivação. Aumentamos o expoente e dividimos pelo novo expoente para compensar a derivada posterior. A constante C aparece porque qualquer constante desaparece quando derivada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
