insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000300401', '40000000-0000-4000-8000-000000030040', 'Integre', '$\int x^5 \,dx=\frac{x^6}{6}+C.$', 1), ('70000000-0000-4000-8000-000000300402', '40000000-0000-4000-8000-000000030040', 'Avalie os limites', '$\left.\frac{x^6}{6}\right|_0^1.$', 2), ('70000000-0000-4000-8000-000000300403', '40000000-0000-4000-8000-000000030040', 'Simplifique', '$\frac{1}{6}.$', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000030041', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000006', 'multiple_choice', 'easy', 'published', 'Se $F(x)=\int_0^x t^1 \,dt$, qual é $F^{\prime}(x)$?')
