insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000500311', '40000000-0000-4000-8000-000000050031', 'A', '$1$', 1), ('50000000-0000-4000-8000-000000500312', '40000000-0000-4000-8000-000000050031', 'B', '$3$', 2), ('50000000-0000-4000-8000-000000500313', '40000000-0000-4000-8000-000000050031', 'C', '$-1$', 3), ('50000000-0000-4000-8000-000000500314', '40000000-0000-4000-8000-000000050031', 'D', '$2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000050031', '50000000-0000-4000-8000-000000500311') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000050031', '30000000-0000-4000-8000-000000000031', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000500311', '40000000-0000-4000-8000-000000050031', 'Ao substituir x igual a zero, aparece a forma indeterminada zero sobre zero.', 1), ('60000000-0000-4000-8000-000000500312', '40000000-0000-4000-8000-000000050031', 'Derive numerador e denominador uma vez.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000050031', '$1$.', 'A regra de L’Hôpital só pode ser usada depois de confirmar uma forma indeterminada adequada. Aqui, seno de zero e zero no denominador produzem zero sobre zero. Derivar os dois lados da fração transforma o limite em uma avaliação direta, pois a nova razão deixa de ser indeterminada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000500311', '40000000-0000-4000-8000-000000050031', 'Teste a substituição', '$\sin(0)/0=0/0.$', 1), ('70000000-0000-4000-8000-000000500312', '40000000-0000-4000-8000-000000050031', 'Derive numerador e denominador', '$(\sin(1x))^{\prime}=1\cos(1x) e (x)^{\prime}=1.$', 2), ('70000000-0000-4000-8000-000000500313', '40000000-0000-4000-8000-000000050031', 'Avalie o novo limite', '$1\cos(0)=1.$', 3)
