insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060039', '$\frac{(x^2+9)^2}{2}+C$.', 'Uma integral não é uma receita isolada: ela desfaz uma derivada ou acumula pequenas variações. O caminho seguro é identificar a estrutura da função, escolher a regra compatível e verificar o resultado derivando-o ou comparando a área acumulada. A constante de integração só aparece quando não há limites definidos.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600391', '40000000-0000-4000-8000-000000060039', 'Escolha a substituição', '$u=x^2+9 e du=2x dx.$', 1), ('70000000-0000-4000-8000-000000600392', '40000000-0000-4000-8000-000000060039', 'Reescreva a integral', '$\int u du=\frac{u^2}{2}+C.$', 2), ('70000000-0000-4000-8000-000000600393', '40000000-0000-4000-8000-000000060039', 'Retorne a x', '$\frac{(x^2+9)^2}{2}+C.$', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060040', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000008', 'multiple_choice', 'medium', 'published', 'Calcule $\int 2x(x^2+10) dx$.')
