insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700121', '40000000-0000-4000-8000-000000070012', 'Exponencie os dois lados com base e.', 1), ('60000000-0000-4000-8000-000000700122', '40000000-0000-4000-8000-000000070012', 'Lembre que o logaritmo natural só aceita entradas positivas.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070012', '$x=e^{2}$.', 'O logaritmo natural e a exponencial de base e são funções inversas. Ao aplicar a exponencial aos dois lados, o logaritmo é desfeito e resta x. A solução encontrada é automaticamente positiva, portanto respeita o domínio do logaritmo e não exige descartar nenhuma raiz adicional.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700121', '40000000-0000-4000-8000-000000070012', 'Identifique a informação', '$\ln(x)$ é definido somente para valores positivos de x.', 1), ('70000000-0000-4000-8000-000000700122', '40000000-0000-4000-8000-000000070012', 'Escreva a condição', '$e^{\ln(x)}=e^{2}$.', 2), ('70000000-0000-4000-8000-000000700123', '40000000-0000-4000-8000-000000070012', 'Faça o cálculo', '$x=e^{2}$.', 3), ('70000000-0000-4000-8000-000000700124', '40000000-0000-4000-8000-000000070012', 'Interprete o resultado', 'A exponencial desfaz o logaritmo natural.', 4), ('70000000-0000-4000-8000-000000700125', '40000000-0000-4000-8000-000000070012', 'Confira a restrição', '$e^{2}>0$, logo a condição de domínio é satisfeita.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070013', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'easy', 'published', 'Se $f(x)=4x-3$, qual é $f^{-1}(x)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700131', '40000000-0000-4000-8000-000000070013', 'A', '$\frac{x+3}{4}$', 1), ('50000000-0000-4000-8000-000000700132', '40000000-0000-4000-8000-000000070013', 'B', '$\frac{x-3}{4}$', 2), ('50000000-0000-4000-8000-000000700133', '40000000-0000-4000-8000-000000070013', 'C', '$4x+3$', 3), ('50000000-0000-4000-8000-000000700134', '40000000-0000-4000-8000-000000070013', 'D', '$\frac{4}{x+3}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000070013', '50000000-0000-4000-8000-000000700131') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070013', '30000000-0000-4000-8000-000000000015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700131', '40000000-0000-4000-8000-000000070013', 'Troque f de x por y e isole x.', 1), ('60000000-0000-4000-8000-000000700132', '40000000-0000-4000-8000-000000070013', 'A inversa desfaz a multiplicação por 4 e a subtração de 3.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070013', '$f^{-1}(x)=\frac{x+3}{4}$.', 'Para encontrar uma inversa, começamos com a saída y e recuperamos a entrada x. A ordem das operações precisa ser desfeita ao contrário: primeiro somamos o termo que havia sido subtraído, depois dividimos pelo coeficiente. A fórmula final pode ser conferida compondo f com sua inversa e obtendo x.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700131', '40000000-0000-4000-8000-000000070013', 'Identifique a informação', '$y=4x-3$.', 1), ('70000000-0000-4000-8000-000000700132', '40000000-0000-4000-8000-000000070013', 'Escreva a condição', '$y+3=4x$.', 2), ('70000000-0000-4000-8000-000000700133', '40000000-0000-4000-8000-000000070013', 'Faça o cálculo', '$x=\frac{y+3}{4}$.', 3), ('70000000-0000-4000-8000-000000700134', '40000000-0000-4000-8000-000000070013', 'Interprete o resultado', 'Troque y por x para nomear a função inversa.', 4), ('70000000-0000-4000-8000-000000700135', '40000000-0000-4000-8000-000000070013', 'Confira a restrição', '$f(f^{-1}(x))=x$ confirma a inversão.', 5)
