insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070020', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'medium', 'published', 'Resolva, nos reais, $\ln(x)=10$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700201', '40000000-0000-4000-8000-000000070020', 'A', '$x=e^{10}$', 1), ('50000000-0000-4000-8000-000000700202', '40000000-0000-4000-8000-000000070020', 'B', '$x=10e$', 2), ('50000000-0000-4000-8000-000000700203', '40000000-0000-4000-8000-000000070020', 'C', '$x=e^{- 10}$', 3), ('50000000-0000-4000-8000-000000700204', '40000000-0000-4000-8000-000000070020', 'D', '$x=10$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000070020', '50000000-0000-4000-8000-000000700201') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070020', '30000000-0000-4000-8000-000000000015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700201', '40000000-0000-4000-8000-000000070020', 'Exponencie os dois lados com base e.', 1), ('60000000-0000-4000-8000-000000700202', '40000000-0000-4000-8000-000000070020', 'Lembre que o logaritmo natural só aceita entradas positivas.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070020', '$x=e^{10}$.', 'O logaritmo natural e a exponencial de base e são funções inversas. Ao aplicar a exponencial aos dois lados, o logaritmo é desfeito e resta x. A solução encontrada é automaticamente positiva, portanto respeita o domínio do logaritmo e não exige descartar nenhuma raiz adicional.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700201', '40000000-0000-4000-8000-000000070020', 'Identifique a informação', '$\ln(x)$ é definido somente para valores positivos de x.', 1), ('70000000-0000-4000-8000-000000700202', '40000000-0000-4000-8000-000000070020', 'Escreva a condição', '$e^{\ln(x)}=e^{10}$.', 2), ('70000000-0000-4000-8000-000000700203', '40000000-0000-4000-8000-000000070020', 'Faça o cálculo', '$x=e^{10}$.', 3), ('70000000-0000-4000-8000-000000700204', '40000000-0000-4000-8000-000000070020', 'Interprete o resultado', 'A exponencial desfaz o logaritmo natural.', 4), ('70000000-0000-4000-8000-000000700205', '40000000-0000-4000-8000-000000070020', 'Confira a restrição', '$e^{10}>0$, logo a condição de domínio é satisfeita.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070021', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'easy', 'published', 'Partindo de $y=x^2$, qual transformação produz $g(x)=(x-2)^2+1$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700211', '40000000-0000-4000-8000-000000070021', 'A', 'Deslocar 2 unidades à direita e 1 para cima.', 1), ('50000000-0000-4000-8000-000000700212', '40000000-0000-4000-8000-000000070021', 'B', 'Deslocar 2 unidades à esquerda e 1 para cima.', 2), ('50000000-0000-4000-8000-000000700213', '40000000-0000-4000-8000-000000070021', 'C', 'Deslocar 1 unidades à direita e 2 para cima.', 3), ('50000000-0000-4000-8000-000000700214', '40000000-0000-4000-8000-000000070021', 'D', 'Refletir no eixo x e deslocar para cima.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000070021', '50000000-0000-4000-8000-000000700211') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070021', '30000000-0000-4000-8000-000000000014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700211', '40000000-0000-4000-8000-000000070021', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 1), ('60000000-0000-4000-8000-000000700212', '40000000-0000-4000-8000-000000070021', 'O termo somado fora da função controla o deslocamento vertical.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070021', 'Deslocar 2 unidades à direita e 1 para cima.', 'Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700211', '40000000-0000-4000-8000-000000070021', 'Identifique a informação', '$g(x)=(x-2)^2+1$ vem de uma parábola padrão.', 1), ('70000000-0000-4000-8000-000000700212', '40000000-0000-4000-8000-000000070021', 'Escreva a condição', '$x-2$ controla a posição horizontal.', 2), ('70000000-0000-4000-8000-000000700213', '40000000-0000-4000-8000-000000070021', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(2,1)$.', 3), ('70000000-0000-4000-8000-000000700214', '40000000-0000-4000-8000-000000070021', 'Interprete o resultado', 'Isso equivale a mover para a direita e depois para cima.', 4), ('70000000-0000-4000-8000-000000700215', '40000000-0000-4000-8000-000000070021', 'Confira a restrição', 'A abertura continua para cima, pois o coeficiente quadrático é positivo.', 5)
