insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700261', '40000000-0000-4000-8000-000000070026', 'Identifique a informação', '$g(x)=(x-7)^2+6$ vem de uma parábola padrão.', 1), ('70000000-0000-4000-8000-000000700262', '40000000-0000-4000-8000-000000070026', 'Escreva a condição', '$x-7$ controla a posição horizontal.', 2), ('70000000-0000-4000-8000-000000700263', '40000000-0000-4000-8000-000000070026', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(7,6)$.', 3), ('70000000-0000-4000-8000-000000700264', '40000000-0000-4000-8000-000000070026', 'Interprete o resultado', 'Isso equivale a mover para a direita e depois para cima.', 4), ('70000000-0000-4000-8000-000000700265', '40000000-0000-4000-8000-000000070026', 'Confira a restrição', 'A abertura continua para cima, pois o coeficiente quadrático é positivo.', 5)
