insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070041', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'easy', 'published', 'Para qual valor de $c$ a função $f(x)=\begin{cases}x+2,&x<2\\c,&x\ge2\end{cases}$ é contínua em $x=2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700411', '40000000-0000-4000-8000-000000070041', 'A', '$4$', 1), ('50000000-0000-4000-8000-000000700412', '40000000-0000-4000-8000-000000070041', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000700413', '40000000-0000-4000-8000-000000070041', 'C', '$5$', 3), ('50000000-0000-4000-8000-000000700414', '40000000-0000-4000-8000-000000070041', 'D', '$0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000070041', '50000000-0000-4000-8000-000000700411') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070041', '30000000-0000-4000-8000-000000000019', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700411', '40000000-0000-4000-8000-000000070041', 'Para haver continuidade, o limite pela esquerda deve coincidir com o valor da função.', 1), ('60000000-0000-4000-8000-000000700412', '40000000-0000-4000-8000-000000070041', 'A expressão da esquerda vale x mais 2.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070041', '$c=4$.', 'Em uma função definida por partes, a continuidade no ponto de troca depende de três valores compatíveis: limite pela esquerda, limite pela direita e valor da função. Como o lado direito é constante c, basta escolher c igual ao valor que a expressão da esquerda se aproxima quando x tende ao ponto de corte.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700411', '40000000-0000-4000-8000-000000070041', 'Identifique a informação', 'O possível salto ocorre no ponto $x=2$.', 1), ('70000000-0000-4000-8000-000000700412', '40000000-0000-4000-8000-000000070041', 'Escreva a condição', '$lim_{x\to2^-}(x+2)=2+2$.', 2), ('70000000-0000-4000-8000-000000700413', '40000000-0000-4000-8000-000000070041', 'Faça o cálculo', '$lim_{x\to2^-}f(x)=4$.', 3), ('70000000-0000-4000-8000-000000700414', '40000000-0000-4000-8000-000000070041', 'Interprete o resultado', 'O valor do lado direito é $f(2)=c$.', 4), ('70000000-0000-4000-8000-000000700415', '40000000-0000-4000-8000-000000070041', 'Confira a restrição', '$c=4$ iguala limite e valor da função.', 5)
