insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000800051', '40000000-0000-4000-8000-000000080005', 'Velocidade instantânea é a derivada da posição.', 1), ('60000000-0000-4000-8000-000000800052', '40000000-0000-4000-8000-000000080005', 'Derive antes de substituir o instante.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080005', '$v(2)=17$.', 'A derivada transforma a posição em velocidade porque mede a variação instantânea no tempo. O termo quadrático gera uma expressão linear e o termo linear contribui com uma constante negativa. Só depois de obter a regra geral de velocidade substituímos o instante pedido; isso evita usar uma taxa média por engano.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
