insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800111', '40000000-0000-4000-8000-000000080011', 'A', '$2x^1$', 1), ('50000000-0000-4000-8000-000000800112', '40000000-0000-4000-8000-000000080011', 'B', '$1x^1$', 2), ('50000000-0000-4000-8000-000000800113', '40000000-0000-4000-8000-000000080011', 'C', '$2x^2$', 3), ('50000000-0000-4000-8000-000000800114', '40000000-0000-4000-8000-000000080011', 'D', '$3x^1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000080011', '50000000-0000-4000-8000-000000800111') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000080011', '30000000-0000-4000-8000-000000000023', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000800111', '40000000-0000-4000-8000-000000080011', 'Use a regra da potência.', 1), ('60000000-0000-4000-8000-000000800112', '40000000-0000-4000-8000-000000080011', 'O coeficiente original continua multiplicando o resultado.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080011', '$f^{\prime}(x)=2x^1$.', 'A regra da potência multiplica o coeficiente pelo expoente e reduz esse expoente em uma unidade. Como a função tem um coeficiente externo, ele participa da multiplicação. É importante reduzir somente o expoente de x: alterar a potência sem ajustar o coeficiente produz um resultado que não devolve a função original ao ser integrado.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000800111', '40000000-0000-4000-8000-000000080011', 'Observe a estrutura', '$f(x)=1x^{2}$', 1), ('70000000-0000-4000-8000-000000800112', '40000000-0000-4000-8000-000000080011', 'Escolha a regra', 'O expoente é 11.', 2), ('70000000-0000-4000-8000-000000800113', '40000000-0000-4000-8000-000000080011', 'Calcule', '$f^{\prime}(x)=1\cdot2x^1$', 3), ('70000000-0000-4000-8000-000000800114', '40000000-0000-4000-8000-000000080011', 'Interprete', '$f^{\prime}(x)=2x^1$', 4), ('70000000-0000-4000-8000-000000800115', '40000000-0000-4000-8000-000000080011', 'Confira', 'A potência caiu de 2 para 1.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000080012', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000010', 'multiple_choice', 'easy', 'published', 'Calcule a derivada de $f(x)=2x^{3}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800121', '40000000-0000-4000-8000-000000080012', 'A', '$6x^2$', 1), ('50000000-0000-4000-8000-000000800122', '40000000-0000-4000-8000-000000080012', 'B', '$2x^2$', 2), ('50000000-0000-4000-8000-000000800123', '40000000-0000-4000-8000-000000080012', 'C', '$6x^3$', 3), ('50000000-0000-4000-8000-000000800124', '40000000-0000-4000-8000-000000080012', 'D', '$4x^2$', 4)
