insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080020', '$f^{\prime}(x)=110x^10$.', 'A regra da potência multiplica o coeficiente pelo expoente e reduz esse expoente em uma unidade. Como a função tem um coeficiente externo, ele participa da multiplicação. É importante reduzir somente o expoente de x: alterar a potência sem ajustar o coeficiente produz um resultado que não devolve a função original ao ser integrado.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000800201', '40000000-0000-4000-8000-000000080020', 'Observe a estrutura', '$f(x)=10x^{11}$', 1), ('70000000-0000-4000-8000-000000800202', '40000000-0000-4000-8000-000000080020', 'Escolha a regra', 'O expoente é 101.', 2), ('70000000-0000-4000-8000-000000800203', '40000000-0000-4000-8000-000000080020', 'Calcule', '$f^{\prime}(x)=10\cdot11x^10$', 3), ('70000000-0000-4000-8000-000000800204', '40000000-0000-4000-8000-000000080020', 'Interprete', '$f^{\prime}(x)=110x^10$', 4), ('70000000-0000-4000-8000-000000800205', '40000000-0000-4000-8000-000000080020', 'Confira', 'A potência caiu de 11 para 10.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000080021', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000010', 'multiple_choice', 'easy', 'published', 'Se $f(x)=x(x+1)$, qual é $f^{\prime}(x)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800211', '40000000-0000-4000-8000-000000080021', 'A', '$2x+1$', 1), ('50000000-0000-4000-8000-000000800212', '40000000-0000-4000-8000-000000080021', 'B', '$x+1$', 2), ('50000000-0000-4000-8000-000000800213', '40000000-0000-4000-8000-000000080021', 'C', '$2x$', 3), ('50000000-0000-4000-8000-000000800214', '40000000-0000-4000-8000-000000080021', 'D', '$x^2+1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000080021', '50000000-0000-4000-8000-000000800211') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000080021', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000800211', '40000000-0000-4000-8000-000000080021', 'Você pode expandir o produto ou aplicar a regra do produto.', 1), ('60000000-0000-4000-8000-000000800212', '40000000-0000-4000-8000-000000080021', 'A derivada de x é 1.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080021', '$f^{\prime}(x)=2x+1$.', 'A regra do produto considera a variação dos dois fatores, por isso não basta derivar apenas um deles. Também é possível expandir primeiro e derivar termo a termo. As duas rotas chegam ao mesmo resultado e servem como verificação uma da outra; essa dupla leitura é útil para evitar esquecer uma parcela da derivada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000800211', '40000000-0000-4000-8000-000000080021', 'Observe a estrutura', '$f(x)=x^2+1x$', 1), ('70000000-0000-4000-8000-000000800212', '40000000-0000-4000-8000-000000080021', 'Escolha a regra', 'Use a regra da potência em cada termo.', 2), ('70000000-0000-4000-8000-000000800213', '40000000-0000-4000-8000-000000080021', 'Calcule', '$f^{\prime}(x)=2x+1$', 3), ('70000000-0000-4000-8000-000000800214', '40000000-0000-4000-8000-000000080021', 'Interprete', 'A expressão é uma função linear.', 4), ('70000000-0000-4000-8000-000000800215', '40000000-0000-4000-8000-000000080021', 'Confira', '$1(x+1)+x(1)=2x+1$ confirma a regra do produto.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000080022', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000010', 'multiple_choice', 'easy', 'published', 'Se $f(x)=x(x+2)$, qual é $f^{\prime}(x)$?')
