insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800281', '40000000-0000-4000-8000-000000080028', 'A', '$2x+8$', 1), ('50000000-0000-4000-8000-000000800282', '40000000-0000-4000-8000-000000080028', 'B', '$x+8$', 2), ('50000000-0000-4000-8000-000000800283', '40000000-0000-4000-8000-000000080028', 'C', '$2x$', 3), ('50000000-0000-4000-8000-000000800284', '40000000-0000-4000-8000-000000080028', 'D', '$x^2+8$', 4)
