insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000800281', '40000000-0000-4000-8000-000000080028', 'Você pode expandir o produto ou aplicar a regra do produto.', 1), ('60000000-0000-4000-8000-000000800282', '40000000-0000-4000-8000-000000080028', 'A derivada de x é 1.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080028', '$f^{\prime}(x)=2x+8$.', 'A regra do produto considera a variação dos dois fatores, por isso não basta derivar apenas um deles. Também é possível expandir primeiro e derivar termo a termo. As duas rotas chegam ao mesmo resultado e servem como verificação uma da outra; essa dupla leitura é útil para evitar esquecer uma parcela da derivada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
