insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000800501', '40000000-0000-4000-8000-000000080050', 'Observe a estrutura', 'No eixo x, a coordenada vertical vale zero.', 1), ('70000000-0000-4000-8000-000000800502', '40000000-0000-4000-8000-000000080050', 'Escolha a regra', '$x^2-100=0$', 2), ('70000000-0000-4000-8000-000000800503', '40000000-0000-4000-8000-000000080050', 'Calcule', '$(x-10)(x+10)=0$', 3), ('70000000-0000-4000-8000-000000800504', '40000000-0000-4000-8000-000000080050', 'Interprete', '$x=10$ ou $x=-10$', 4), ('70000000-0000-4000-8000-000000800505', '40000000-0000-4000-8000-000000080050', 'Confira', '$f(10)=0$ confirma o ponto escolhido.', 5)
